   589  void BmffImage::parseTiff(uint32_t root_tag, uint64_t length, uint64_t start) {
   590    Internal::enforce(start <= io_->size(), ErrorCode::kerCorruptedMetadata);
   591    Internal::enforce(length <= io_->size() - start, ErrorCode::kerCorruptedMetadata);
   592    Internal::enforce(start <= static_cast<uint64_t>(std::numeric_limits<int64_t>::max()),
   593                      ErrorCode::kerCorruptedMetadata);
   594    Internal::enforce(length <= std::numeric_limits<size_t>::max(), ErrorCode::kerCorruptedMetadata);
   595
   596    // read and parse exif data
   597    const size_t restore = io_->tell();
   598    DataBuf exif(static_cast<size_t>(length));
   599    io_->seek(static_cast<int64_t>(start), BasicIo::beg);
   600    if (exif.size() > 8 && io_->read(exif.data(), exif.size()) == exif.size()) {
   601      // hunt for "II" or "MM"
   602      const size_t eof = std::numeric_limits<size_t>::max();  // impossible value for punt
   603      size_t punt = eof;
   604      for (size_t i = 0; i < exif.size() - 9 && punt == eof; ++i) {
   605        auto charCurrent = exif.read_uint8(i);
   606        auto charNext = exif.read_uint8(i + 1);
   607        if (charCurrent == charNext && (charCurrent == 'I' || charCurrent == 'M'))
   608          punt = i;
   609      }
   610      if (punt != eof) {
   611        Internal::TiffParserWorker::decode(exifData(), iptcData(), xmpData(), exif.c_data(punt), exif.size() - punt,
   612                                           root_tag, Internal::TiffMapping::findDecoder);
   613      }
   614    }
   615    io_->seek(restore, BasicIo::beg);
   616  }
