   618  void BmffImage::parseTiff(uint32_t root_tag, uint64_t length) {
   619    if (length > 8) {
   620      Internal::enforce(length - 8 <= io_->size() - io_->tell(), ErrorCode::kerCorruptedMetadata);
   621      Internal::enforce(length - 8 <= std::numeric_limits<size_t>::max(), ErrorCode::kerCorruptedMetadata);
   622      DataBuf data(static_cast<size_t>(length - 8u));
   623      const size_t bufRead = io_->read(data.data(), data.size());
   624
   625      if (io_->error())
   626        throw Error(ErrorCode::kerFailedToReadImageData);
   627      if (bufRead != data.size())
   628        throw Error(ErrorCode::kerInputDataReadFailed);
   629
   630      Internal::TiffParserWorker::decode(exifData(), iptcData(), xmpData(), data.c_data(), data.size(), root_tag,
   631                                         Internal::TiffMapping::findDecoder);
   632    }
   633  }
