   635  void BmffImage::parseXmp(uint64_t length, uint64_t start) {
   636    Internal::enforce(start <= io_->size(), ErrorCode::kerCorruptedMetadata);
   637    Internal::enforce(length <= io_->size() - start, ErrorCode::kerCorruptedMetadata);
   638
   639    const size_t restore = io_->tell();
   640    io_->seek(static_cast<int64_t>(start), BasicIo::beg);
   641
   642    auto lengthSizeT = static_cast<size_t>(length);
   643    DataBuf xmp(lengthSizeT + 1);
   644    xmp.write_uint8(lengthSizeT, 0);  // ensure xmp is null terminated!
   645    if (io_->read(xmp.data(), lengthSizeT) != lengthSizeT)
   646      throw Error(ErrorCode::kerInputDataReadFailed);
   647    if (io_->error())
   648      throw Error(ErrorCode::kerFailedToReadImageData);
   649    try {
   650      Exiv2::XmpParser::decode(xmpData(), std::string(xmp.c_str()));
   651    } catch (...) {
   652      throw Error(ErrorCode::kerFailedToReadImageData);
   653    }
   654
   655    io_->seek(restore, BasicIo::beg);
   656  }
